import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Number> angka = new ArrayList<>();
        tambahKelipatan(angka, 5);
        System.out.println(angka);

        List<Object> campur = new ArrayList<>();
        campur.add("x");
        tambahKelipatan(campur, 2);
        System.out.println(campur);
    }

    static void tambahKelipatan(List<? super Integer> tujuan, int n) {
        for (int i = 1; i <= 3; i++) {
            tujuan.add(n * i);
        }
    }
}

